import { useEffect, useRef, useState } from 'react';
import { Button, Dialog } from '@/components/ui';

export function ConfirmDeleteDialog() {
  const [open, setOpen] = useState(false);
  const [closedOnce, setClosedOnce] = useState(false);
  const dialogRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;

    function handleAfterHide() {
      // Track that the dialog was closed at least once (analytics)
      setClosedOnce(true);
    }

    dialog.addEventListener('wa-after-hide', handleAfterHide);
    return () => {
      dialog.removeEventListener('wa-after-hide', handleAfterHide);
    };
  }, []);

  return (
    <>
      <Button variant="danger" onClick={() => setOpen(true)}>
        Delete account
      </Button>

      <Dialog
        ref={dialogRef}
        open={open}
        label="Delete account?"
        onHide={() => setOpen(false)}
      >
        <p>This action cannot be undone. All your data will be permanently deleted.</p>

        <div slot="footer" className="wa-cluster wa-justify-content-end wa-gap-s">
          <Button
            variant="neutral"
            onClick={() => dialogRef.current?.requestClose()}
          >
            Cancel
          </Button>
          <Button variant="danger" onClick={() => setOpen(false)}>
            Yes, delete
          </Button>
        </div>
      </Dialog>

      {closedOnce && (
        <p className="wa-caption-s">Dialog was closed.</p>
      )}
    </>
  );
}

