<script setup lang="ts">
import { ref, computed } from 'vue';
import { useAuth } from '@/composables/useAuth';
import { Button, Card, Input } from '@/components/ui';

const auth = useAuth();

const email = ref('');
const password = ref('');
const submitError = ref<string | null>(null);

const isEmailValid = computed(() => {
  if (!email.value) return false;
  return /^[\w.-]+@[\w.-]+\.\w+$/.test(email.value);
});

const isFormValid = computed(
  () => isEmailValid.value && password.value.length >= 8
);

async function handleSubmit(e: Event) {
  e.preventDefault();
  submitError.value = null;
  if (!isFormValid.value) {
    submitError.value = 'Please fix the errors above.';
    return;
  }
  try {
    await auth.signIn(email.value, password.value);
  } catch (err) {
    submitError.value = (err as Error).message;
  }
}
</script>

<template>
  <Card>
    <form class="wa-stack wa-gap-m" @submit="handleSubmit">
      <Input
        v-model="email"
        label="Email"
        type="email"
        required
        :hint="email && !isEmailValid ? 'Invalid email format' : undefined"
      />
      <Input
        v-model="password"
        label="Password"
        type="password"
        password-toggle
        required
        :hint="password && password.length < 8 ? 'Min 8 characters' : undefined"
      />
      <Button
        variant="brand"
        type="submit"
        :loading="auth.loading.value"
        :disabled="!isFormValid"
      >
        Sign In
      </Button>
      <p v-if="submitError" class="wa-caption-s">{{ submitError }}</p>
    </form>
  </Card>
</template>

