import { Component, CUSTOM_ELEMENTS_SCHEMA, OnInit, effect, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { trigger, transition, style, animate } from '@angular/animations';
import { ButtonComponent, CardComponent } from '@/components/ui';

interface User {
  id: number;
  name: string;
  email: string;
}

@Component({
  selector: 'app-user-list',
  standalone: true,
  imports: [ButtonComponent, CardComponent],
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
  animations: [
    trigger('fadeIn', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(8px)' }),
        animate('220ms ease-out', style({ opacity: 1, transform: 'translateY(0)' })),
      ]),
    ]),
  ],
  template: `
    <div class="wa-stack wa-gap-m">
      <h2 class="wa-heading-m">Users ({{ users().length }})</h2>

      @if (loading()) {
        <p class="wa-caption-s">Loading...</p>
      }

      @for (user of users(); track user.id) {
        <k-card @fadeIn>
          <strong>{{ user.name }}</strong>
          <p class="wa-caption-s">{{ user.email }}</p>
        </k-card>
      }

      <k-button variant="brand" (click)="reload()">Reload</k-button>
    </div>
  `,
})
export class UserListComponent implements OnInit {
  private http = inject(HttpClient);

  users = signal<User[]>([]);
  loading = signal(false);

  constructor() {
    effect(() => {
      console.log(`Now showing ${this.users().length} users`);
    });
  }

  ngOnInit() {
    this.reload();
  }

  reload() {
    this.loading.set(true);
    this.http.get<User[]>('/api/users').subscribe({
      next: (data) => {
        this.users.set(data);
        this.loading.set(false);
      },
      error: () => {
        this.loading.set(false);
      },
    });
  }
}

